let db,state;try{state=JSON.parse(localStorage.getItem('binary-school-v1'))||{done:[],notes:{},exam:false,name:''}}catch{state={done:[],notes:{},exam:false,name:''}}let currentBytes=null;const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function save(){try{localStorage.setItem('binary-school-v1',JSON.stringify(state));return true}catch{return false}}
let activeLessonId=null,lastRenderedHash=null;
function persistDraft(){if(activeLessonId===null)return;const field=$('#notes');if(!field)return;state.notes[activeLessonId]=field.value;const report=$('#practicalevidence');if(report){state.evidence=state.evidence||{};state.evidence[activeLessonId]=report.value}const ok=save();const status=$('#notestatus');if(status)status.textContent=ok?'Saved in this browser.':'Could not save: browser storage is unavailable or full. Copy your notes before leaving.';return ok}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2500)}const coreLessons=()=>db.lessons.filter(l=>l.course!=='secure');const following=id=>{const list=activeStudyLessons();return list[list.findIndex(l=>l.id===id)+1]};const done=id=>state.done.includes(id),lessons=c=>db.lessons.filter(l=>l.course===c),pct=c=>Math.round(100*lessons(c).filter(l=>done(l.id)).length/lessons(c).length),next=()=>activeStudyLessons().find(l=>!done(l.id))||activeStudyLessons()[0];function cards(){return `<div class="cards">${db.courses.map((c,i)=>`<a class="card" href="#course/${c[0]}"><div class="art ${c[5]}"><span class="num">COURSE ${c[1]}</span><span class="glyph">${({'assembly':'mov_','foundations':'{ x }','machine':'0x','patterns':'if_','calls':'call','ghidra':'⌘','types':'*p','debug':'>_','dynamic':'bp_','windows':'PE','anti':'xor','workshop':'lab','secure':'?_'})[c[0]]}</span></div><div class="cardbody"><span class="eyebrow">${c[0]==='secure'?'SUPPLEMENT':c[0]==='workshop'?'INDEPENDENT PRACTICE':'STEP '+c[1]}</span><h3>${c[2]}</h3><p>${c[4]}</p><progress max="100" value="${pct(c[0])}" aria-label="${esc(c[2])} study completion">${pct(c[0])}%</progress><div class="cardfooter"><span>${lessons(c[0]).length} lessons · ${c[0]==='secure'?'Optional extension':i===0?'Beginner':'Progressive practice'}</span><span>${pct(c[0])}% →</span></div></div></a>`).join('')}</div>`}function home(){return `<div class="titlebar"><div><div class="eyebrow">YOUR LEARNING JOURNEY</div><h1>Learn what’s underneath.</h1><p>A complete study path from first instructions to independent investigations.</p></div><span class="pill">GCC + MSVC · x86 + x64</span></div><section class="hero"><div><div class="eyebrow">THE REVERSE ENGINEERING PATH</div><h2>Understand the code.<br>Even without the source.</h2><p>Study assembly, recover C, debug Linux and Windows programs, and investigate anti-analysis techniques. One small discovery at a time.</p><a class="btn light" href="${state.learningPath?'#lesson/'+next().id:'#paths'}">${state.learningPath?'Continue your study path':'Choose your study path'} &nbsp; →</a></div><div class="terminal"><div class="termbar">● ● ● &nbsp; first-discovery.c</div><pre>int transform(int input) {\n    return input * 3 + 7;\n}\n\n<span style="color:#83a69a">// A little curiosity goes a long way.</span>\n(gdb) break transform\nBreakpoint 1 set. You’re in.</pre></div></section><div class="stats"><div class="stat"><i>▤</i><div><strong>${db.courses.length}</strong><small>Connected courses</small></div></div><div class="stat"><i>✓</i><div><strong>${state.done.length} / ${db.lessons.length}</strong><small>Study/completion entries</small></div></div><div class="stat"><i>⌘</i><div><strong>${state.exam?'Passed':'1'}</strong><small>Introductory patch exercise</small></div></div></div><p><a class="btn secondary" href="#lesson/0">Set up your lab first →</a> <a class="btn secondary" href="#paths">Diagnostic & study paths →</a> <a class="btn secondary" href="#readiness">Review practical readiness →</a></p><div class="sectionhead"><h2>Your learning path</h2><span>Foundations first. Confidence follows.</span></div>${cards()}<p><a class="btn secondary" href="#syllabus">View syllabus coverage & study strategy →</a></p><div class="notice"><strong>Localhost edition.</strong> Written lessons, exercises, downloads, progress, and patch practice work offline. YouTube and external references need internet. <a href="#resources"><u>Export progress before moving to another browser or laptop.</u></a><br><br><strong>A lab, not just a playlist.</strong> Written teaching, worked examples, related YouTube lectures, 10 substantial investigations, a comprehensive mock final, and downloadable lab families. Progress stays in this browser. Local Ghidra/GDB required for tool exercises.</div>`}function course(id){let c=db.courses.find(c=>c[0]===id);if(!c)return 'Course not found.';return `<a class="muted" href="#courses">← Learning path</a><h1>${c[3]}</h1><p>${c[4]}</p><span class="pill">${pct(id)}% complete · ${lessons(id).length} learning activities</span><p><a href="#lesson/0">Set up your platform before running any binary →</a></p>${courseLabPanel(id)}<div class="panel"><div class="eyebrow">${id==='assembly'?'NO REVERSE ENGINEERING EXPERIENCE REQUIRED':'RECOMMENDED: COMPLETE THE PREVIOUS COURSE FIRST'}</div>${lessons(id).map((l,i)=>`<a class="lessonrow" href="#lesson/${l.id}"><span class="circle ${done(l.id)?'done':''}">${done(l.id)?'✓':i+1}</span><div><strong>${l.title}</strong><small>${l.level} · Notes + practice + self-review</small></div><span class="arrow">→</span></a>`).join('')}</div>`}function matchBlank(value,expected){let normalize=s=>s.toLowerCase().replace(/\s+/g,'');return expected.split('|').some(a=>normalize(a)===normalize(value))}function blankEditor(l){return '<div class="codeblanks">'+l.template.split(/(\[\[\d+\]\])/).map(part=>{let m=part.match(/^\[\[(\d+)\]\]$/);return m?'<input aria-label="Blank '+(+m[1]+1)+'" id="blank'+m[1]+'" class="codeblank" required autocomplete="off" spellcheck="false" placeholder="'+(+m[1]+1)+'">':esc(part)}).join('')+'</div>'}function lesson(id){let l=db.lessons.find(l=>l.id===Number(id));if(!l)return 'Lesson not found.';let c=db.courses.find(c=>c[0]===l.course);return `<div class="workspace"><div class="lessonnav" role="navigation" aria-label="Lessons in ${esc(c[2])}"><details class="lessonoutline" open><summary>Lessons in this course</summary><div class="lessonlinks"><a href="#course/${l.course}"><b>← ${c[2]}</b></a>${lessons(l.course).map(x=>`<a href="#lesson/${x.id}" class="${x.id===l.id?'selected':''}" ${x.id===l.id?'aria-current="page"':''}>${done(x.id)?'✓':'○'} &nbsp; ${x.title}</a>`).join('')}</div></details></div><article class="lessoncontent"><span class="eyebrow">${c[1]} / ${l.level} assignment</span><h1>${l.title}</h1><div class="panel"><h3>01 &nbsp; Learn the idea</h3><p>${esc(l.body)}</p>${l.code?`<pre>${esc(l.code)}</pre>`:''}${sectionTeaching(l)}${extendedTeaching(l)}<p class="muted">For compiler comparisons, use <a href="https://godbolt.org" target="_blank" rel="noopener"><u>Compiler Explorer ↗</u></a>. See Resources for downloads and official references.</p></div><div class="panel"><h3>02 &nbsp; Watch & explore</h3><p class="muted">${l.teacher}. ${l.id>=42?'Supporting foundations lecture; it does not replace the topic-specific written lesson and references.':'A supporting overview; use the lesson notes above for this specific task.'} Independent creator, no affiliation.</p><details><summary>Load the related YouTube lesson</summary><iframe title="${esc(l.teacher)}" loading="lazy" src="https://www.youtube-nocookie.com/embed/${l.video}" allowfullscreen></iframe></details><p><a href="https://www.youtube.com/watch?v=${l.video}" target="_blank" rel="noopener">Watch on YouTube ↗</a></p></div><div class="panel"><h3>03 &nbsp; ${l.flagDigest?'Interactive flag discovery':l.optional_completion?'Optional checkpoint':'Put it into practice'} ${done(l.id)?'✓':''}</h3><p>${esc(l.task)}</p><form id="answerform"><label class="muted" for="${l.blanks?'blank0':'answer'}">${l.flagDigest?'Flag from the downloaded binary (case-sensitive)':l.blanks?'Fill each blank below (Intel syntax; not case-sensitive).':'Your answer (not case-sensitive)'}</label>${l.blanks?blankEditor(l):''}<div class="answerline">${l.blanks?'':'<input id="answer" autocomplete="off" required placeholder="Investigate, then submit your answer">'}<button class="btn">Check answer →</button></div></form><div class="feedback" id="feedback" role="status"></div><details><summary>Need a hint?</summary><p>${esc(l.hint)}</p></details></div>${l.optional_completion?completionPanel(l):''}${practicalPanel(l)}<div class="panel"><h3>Your lab notebook</h3><label for="notes" class="muted">Record commands, observations, and what surprised you. Saved on this browser.</label><p id="notestatus" role="status">Notes autosave as you type.</p><textarea id="notes" placeholder="What did you discover?">${esc(state.notes[id]||'')}</textarea><button class="btn secondary" id="savenotes">Save notes</button></div><a class="btn" href="${following(l.id)?'#lesson/'+following(l.id).id:state.learningPath?'#paths':'#final'}">${following(l.id)?'Next assignment':state.learningPath?'Review study path':'Open practical final'} →</a></article></div>`}function resources(){return `<div class="eyebrow">YOUR TOOLKIT</div><h1>Everything you need to investigate.</h1>${labResources()}<p>Start with unoptimized x64 builds. Add complexity only after you can explain the simple version.</p><div class="resourcegrid"><div class="panel"><h3>Compiler Explorer ↗</h3><p>Compare C against live GCC and MSVC assembly. Add two compiler panes, select C, and use the same architecture.</p><a href="https://godbolt.org" target="_blank" rel="noopener">Open godbolt.org</a><pre>GCC:  -O0 -g\nMSVC: /Od\n\nThen compare -O2 with /O2.</pre></div><div class="panel"><h3>Download the lab pack</h3><p>Our own small, inspectable programs. Use Linux for ELF execution and Windows for native MSVC execution.</p><p><a download href="labs/lab.c">C source · lab.c</a><br><a download href="labs/lab-gcc">Linux x64 GCC executable</a><br><a download href="labs/build-msvc.bat">MSVC build script</a><br><a download href="labs/practice-gcc">Ghidra patch practice · ELF</a></p><p class="muted">MSVC executables are built on your Windows machine; they are not included as precompiled downloads.</p></div><div class="panel"><h3>Ghidra</h3><p>Create a project, import ELF or PE, run analysis, find strings and follow cross references. Decompiled C is an interpretation.</p><a href="https://github.com/NationalSecurityAgency/ghidra" target="_blank" rel="noopener">Official releases & installation ↗</a><p><a href="https://ghidra.re/ghidra_docs/GhidraClass/Beginner/Introduction_to_Ghidra_Student_Guide.html" target="_blank" rel="noopener">Official beginner guide ↗</a></p></div><div class="panel"><h3>Debugger reference</h3><a href="https://sourceware.org/gdb/current/onlinedocs/gdb/" target="_blank" rel="noopener">GNU GDB manual ↗</a><p><a href="https://learn.microsoft.com/en-us/visualstudio/debugger/debugger-feature-tour" target="_blank" rel="noopener">Visual Studio debugger tour ↗</a></p><pre>break main / run / next / step\nprint x / info registers\nx/8wx $rsp / backtrace\nwatch sum / continue</pre></div></div><div class="panel"><h3>GCC and MSVC are both first-class learning targets</h3><p>Analyze both in Ghidra. Debug Linux builds with GDB; debug MSVC Windows builds in Visual Studio. Do not run a Windows PE directly inside Linux GDB.</p><table style="width:100%;text-align:left;line-height:2"><tr><th>x64 target</th><th>Linux GCC</th><th>Windows MSVC</th></tr><tr><td>Format</td><td>ELF</td><td>PE</td></tr><tr><td>First int argument</td><td>edi</td><td>ecx</td></tr><tr><td>Second int argument</td><td>esi</td><td>edx</td></tr><tr><td>int return</td><td>eax</td><td>eax</td></tr></table></div><div class="panel"><h3>Keep a copy of your progress</h3><p>Progress and notebook entries are local to this browser, with no account sync. Export a backup to move devices.</p><button class="btn secondary" id="export">Export progress</button> <button class="btn secondary" type="button" id="chooseimport">Choose backup to preview</button><input type="file" id="import" accept="application/json" hidden> <button class="btn secondary" id="recoverimport">Preview pre-import recovery</button><p>Selecting a file does not change your progress. Preview it, then merge records or explicitly replace them. Applying either option first stores a recovery snapshot and requests a download of your current progress.</p><div id="importpreview" role="region" aria-label="Backup import preview"></div></div>`}function final(){return `<div class="eyebrow">INTRODUCTORY PRACTICE / ELF DATA PATCH</div><h1>Make the binary say something new.</h1><p><a class="btn secondary" href="#course/workshop">Ready for more? Open the 10 investigations & comprehensive mock final →</a></p><p>Apply what you learned. Preserve a real executable while changing its output.</p><div class="notice"><b>Exam brief:</b> Replace <code>STATUS=PENDING</code> with <code>STATUS=SUCCESS</code>. Both strings are 14 bytes. Preserve every other byte, including the null terminator. ${state.exam?'✓ Previously passed.':''}</div><div class="examgrid"><div class="panel"><h3>01 &nbsp; Choose your workflow</h3><p>Download the GCC ELF and patch it in Ghidra, then upload your export. Or load the same executable into the guided browser byte editor below. This editor changes actual file bytes; it is not Ghidra or GDB.</p><a class="btn secondary" href="labs/final-gcc" download>Download original ELF ↓</a><p><label for="binary">Upload a patched executable</label></p><input id="binary" type="file"><p class="muted">Uploads stay in your browser and are never executed. Maximum size: 1 MB.</p><button class="btn secondary" id="loadbinary">Load original into byte editor</button></div><div class="panel"><h3>02 &nbsp; Inspect & patch</h3><p id="fileinfo">No executable loaded.</p><div id="hexdump" class="hex">Load a file to inspect its output string.</div><p><label for="replacement">Replacement ASCII text · exactly 14 bytes</label></p><input id="replacement" value="STATUS=SUCCESS" maxlength="14"><p><button class="btn secondary" id="patch">Apply string patch</button> <button class="btn secondary" id="downloadpatch">Download patched ELF</button></p></div></div><div class="panel"><h3>03 &nbsp; Validate the executable</h3><p>The checker requires an exact copy of the original except for the specified output string. This narrow final assesses data patching, not arbitrary program repair. Browser checks are practice-level and do not verify identity or tool usage.</p><label for="reason">Explain why this is a persistent change and how you located the string.</label><textarea id="reason" placeholder="Describe your investigation and the bytes you changed..."></textarea><button class="btn" id="grade">Run validation →</button><div id="examfeedback" class="feedback" role="status"></div></div>`}function achievements(){let eligible=coreLessons().every(l=>done(l.id))&&state.exam;return `<div class="eyebrow">YOUR ACHIEVEMENTS</div><h1>Your learning record.</h1><p><a class="btn secondary" href="#readiness">View checkpoints and practical evidence separately →</a></p><p>Complete the ${coreLessons().length} core lessons and the introductory file-patching practice to unlock a personal completion certificate.</p><div class="stats"><div class="stat"><i>✓</i><div><strong>${state.done.length}/${db.lessons.length}</strong><small>Study/completion entries</small></div></div><div class="stat"><i>⌘</i><div><strong>${state.exam?'Passed':'Pending'}</strong><small>Introductory patch exercise</small></div></div><div class="stat"><i>◇</i><div><strong>${eligible?'Unlocked':'In progress'}</strong><small>Completion certificate</small></div></div></div>${eligible?`<div class="panel"><label for="studentname">Name on your certificate</label><input id="studentname" maxlength="80" value="${esc(state.name)}"><p><button class="btn" id="certname">Update name</button> <button class="btn secondary" onclick="window.print()">Print / save as PDF</button></p></div><div class="certificate"><div class="eyebrow">BINARY SCHOOL</div><p>Certificate of Completion</p><h1>${esc(state.name||'Your name')}</h1><p>has completed the</p><h2>Reverse Engineering Study Path</h2><p>Assembly fundamentals · C & assembly · Ghidra analysis · GDB debugging<br>GCC / MSVC · C reconstruction · Windows analysis · Anti-analysis studies</p><p class="muted">Self-paced, unproctored completion record, including self-reported study. Browser-local progress.<br>Not an accredited certification or an independently verified credential.</p></div>`:`<div class="panel"><h3>Your certificate is taking shape.</h3><p>Keep investigating. Each completed lesson brings you closer. The supplement is optional.</p><a class="btn" href="#lesson/${next().id}">Continue learning →</a></div>`}`}
function download(name,bytes,type='application/octet-stream'){let u=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}async function original(){return new Uint8Array(await (await fetch('labs/final-gcc')).arrayBuffer())}function find(bytes,str){let a=new TextEncoder().encode(str);outer:for(let i=0;i<=bytes.length-a.length;i++){for(let j=0;j<a.length;j++)if(bytes[i+j]!==a[j])continue outer;return i}return -1}async function inspect(){let o=await original(),offset=find(o,'STATUS=PENDING');$('#fileinfo').textContent=currentBytes?`${currentBytes.length} bytes · output at file offset 0x${offset.toString(16)}`:'No file loaded';$('#hexdump').textContent=currentBytes?Array.from(currentBytes.slice(offset,offset+15)).map(x=>x.toString(16).padStart(2,'0')).join(' '):''}
function bind(route,arg){if(route==='paths')bindStudyPaths();if(route==='lesson'){activeLessonId=Number(arg);$('#notes').oninput=persistDraft}if(route==='readiness')bindReadiness();if(route==='catalog'){$('#lessonsearch').oninput=()=>{$('#searchresults').innerHTML=searchResults($('#lessonsearch').value)}}if(route==='lesson'){let l=db.lessons.find(l=>l.id===Number(arg));if(!l)return;if($('#checkpractical'))$('#checkpractical').onclick=()=>{const results=l.practical.checks.map((row,i)=>matchBlank($('#practice'+i).value.trim(),row[1]));results.forEach((pass,i)=>$('#practice'+i).setAttribute('aria-invalid',String(!pass)));$('#practicefeedback').textContent=results.every(Boolean)?'Predictions match. Now verify them in the executable and explain the instructions and live state. This does not evaluate your report.':'Revisit prediction(s) '+results.map((ok,i)=>ok?null:i+1).filter(Boolean).join(', ')+'. Try the guided build and compare your assumptions.';if(results.every(Boolean)){state.practicalChecks=state.practicalChecks||[];if(!state.practicalChecks.includes(l.id))state.practicalChecks.push(l.id);save()}};if($('#repairupload'))$('#repairupload').onchange=checkHoldoutRepair;if($('#saveevidence'))$('#saveevidence').onclick=()=>{state.evidence=state.evidence||{};state.evidence[l.id]=$('#practicalevidence').value;const ok=save();$('#evidencestatus').textContent=ok?'Report saved for self-review; its correctness has not been evaluated.':'Could not save. Copy your report before leaving.'};if($('#practicalevidence'))$('#practicalevidence').oninput=()=>{state.evidence=state.evidence||{};state.evidence[l.id]=$('#practicalevidence').value;const ok=save();$('#evidencestatus').textContent=ok?'Draft saved in this browser.':'Storage unavailable. Copy your report before leaving.'};if($('#markstudied'))$('#markstudied').onclick=()=>{if(!done(l.id))state.done.push(l.id);state.notes[arg]=$('#notes').value;save();$('#markstudied').textContent='✓ Marked studied';toast('Self-reported completion saved; not a graded pass')};document.querySelectorAll('[data-review]').forEach(el=>el.onchange=()=>{state.reviews=state.reviews||{};state.reviews[l.id]=state.reviews[l.id]||{};state.reviews[l.id][el.dataset.review]=el.checked;save()});$('#answerform').onsubmit=async e=>{e.preventDefault();if(l.flagDigest){await checkFlag(l);return;}let results=l.blanks?l.blanks.map((v,i)=>matchBlank($('#blank'+i).value,v)):null;let a=l.blanks?'':$('#answer').value.trim().toLowerCase().replace(/\s+/g,' '),expected=l.answer.toLowerCase();let ok=results?results.every(Boolean):a===expected||(expected==='backtrace'&&a==='bt')||(expected==='break main'&&a==='b main');if(results)results.forEach((pass,i)=>{$('#blank'+i).setAttribute('aria-invalid',String(!pass));$('#blank'+i).classList.toggle('incorrect',!pass);$('#blank'+i).classList.toggle('correct',pass)});$('#feedback').className='feedback '+(ok?'success':'error');$('#feedback').textContent=ok?(l.optional_completion?'Checkpoint correct. Complete the practical investigation and self-review before moving on.':'Correct. Assignment completed. Record your investigation in your notebook, then continue.'):(results?'Check blank(s) '+results.map((v,i)=>v?null:i+1).filter(Boolean).join(', ')+'. Your other entries are preserved. Revisit the notes or open the hint.':'Not quite. Revisit the example or open the hint, then try again.');if(ok){state.checkpoints=state.checkpoints||[];if(!state.checkpoints.includes(l.id))state.checkpoints.push(l.id);save()}if(ok&&!l.optional_completion&&!done(l.id)){state.done.push(l.id);save()}};$('#savenotes').onclick=()=>{if(persistDraft())toast('Notebook saved')}}if(route==='resources')bindResources();if(route==='achievements'&&$('#certname'))$('#certname').onclick=()=>{state.name=$('#studentname').value.trim();save();render();focusContent('#studentname')};if(route==='final'){currentBytes=null;$('#loadbinary').onclick=async()=>{currentBytes=await original();await inspect();toast('Original executable loaded')};$('#binary').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1000000){toast('File too large. Limit is 1 MB.');return}currentBytes=new Uint8Array(await f.arrayBuffer());await inspect()};$('#patch').onclick=async()=>{if(!currentBytes)return toast('Load an executable first');let text=$('#replacement').value;if(!/^[\x20-\x7e]{14}$/.test(text))return toast('Use exactly 14 ASCII characters');let off=find(await original(),'STATUS=PENDING');if(currentBytes.length<off+15)return toast('This file is too short');currentBytes.set(new TextEncoder().encode(text),off);await inspect();toast('Bytes patched')};$('#downloadpatch').onclick=()=>currentBytes?download('final-patched-gcc',currentBytes):toast('Load an executable first');$('#grade').onclick=async()=>{let feedback=$('#examfeedback');if(!currentBytes){feedback.textContent='Load your patched executable first.';return}if($('#reason').value.trim().length<40){feedback.textContent='Add an explanation of at least 40 characters about your method and persistent change.';return}let expected=await original(),off=find(expected,'STATUS=PENDING');expected.set(new TextEncoder().encode('STATUS=SUCCESS'),off);let ok=expected.length===currentBytes.length&&expected.every((b,i)=>b===currentBytes[i]);feedback.className='feedback '+(ok?'success':'error');feedback.textContent=ok?'Passed: output bytes are correct, the terminator is intact, and every other executable byte is unchanged. Your explanation was recorded, not automatically assessed.':'Not passed: expected the exact original executable with only STATUS=PENDING replaced by STATUS=SUCCESS. Check length, offset, terminator, and your export format.';if(ok){state.exam=true;state.notes.final=$('#reason').value;save()}}}}
function extendedTeaching(l){if(!l.walkthrough)return '';return `<div class="subsection">${binaryDownloads(l)}${holdoutPanel(l)}<h4>Work through it</h4><ol>${l.walkthrough.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${l.lab?`<p><a class="btn secondary" href="labs/full/${encodeURIComponent(l.lab)}" download>Download ${esc(l.lab)} ↓</a> <a href="labs/binary-school-full-labs.zip" download>Full lab pack ↓</a></p>`:''}<details class="worked"><summary>Worked solution & reasoning — attempt first</summary><p>${esc(l.solution)}</p></details><h4>Primary references</h4><ul>${(l.references||[]).map(r=>`<li><a href="${esc(r[1])}" target="_blank" rel="noopener">${esc(r[0])} ↗</a></li>`).join('')}</ul></div>`}
function completionPanel(l){let items=l.review||['I attempted the example or local lab before opening the solution.','I can explain the reasoning without copying the notes.','I checked edge cases and recorded what I still need to practice.'];return `<div class="panel"><h3>04 &nbsp; Self-review, not a graded submission</h3><p>${esc(l.reflection||'Complete the investigation and compare your report with the worked solution.')}</p>${items.map((x,i)=>`<label class="reviewitem"><input type="checkbox" data-review="${i}" ${state.reviews?.[l.id]?.[i]?'checked':''}> <span>${esc(x)}</span></label>`).join('')}<p><button class="btn secondary" id="markstudied">${done(l.id)?'✓ Marked studied':'Mark this lesson studied'}</button></p><p class="muted">You control this completion record. It does not verify tool usage, lab results, or exam readiness.</p></div>`}
function labResources(){return `<div class="panel labdownload"><span class="eyebrow">EXPANDED COURSE LAB PACK</span><h2>Analyze real programs, in progressive variants.</h2><p>Thirteen interactive flag challenges (guided and independent builds), eight comparative x86/x64 case studies with real disassembly and state tables, plus six original Linux GCC lab families; x86/x64 assembly listings; C sources; Windows MSVC build scripts; comparison, repair, and bounded fuzzing helpers.</p><a class="btn" href="labs/interactive-flag-labs.zip" download>Download 13 flag labs ↓</a> <a class="btn secondary" href="labs/comparative-casebook.zip" download>Download comparative casebook ↓</a> <a class="btn secondary" href="labs/binary-school-full-labs.zip" download>Download reconstruction lab pack ↓</a> <a class="btn secondary" href="labs/full/README.txt" target="_blank">Read setup & program contracts ↗</a><p class="muted">Linux x64 executable behavior and all supplied listings were checked here. The x86/32 casebook binaries were statically checked but not executed on this host. MSVC builds and live Windows debugger steps require local Windows verification. Sources are included for self-review; these are not secret exam binaries.</p></div>`}
function syllabus(){return `<div class="eyebrow">CSC-428 ALIGNED STUDY GUIDE</div><h1>Understand it. Demonstrate it. Revisit it.</h1><p>Aligned to the supplied Fall 2026 topic outline and learning outcomes. This independent study site is not affiliated with DSU and does not guarantee a grade. The syllabus assumes C, x86 assembly, and Linux familiarity; use the foundation lessons and official references to close prerequisite gaps.</p><div class="panel"><h3>How to study for transfer, not memorization</h3><ol><li>Predict the small example before using a tool.</li><li>Verify it in GCC and native MSVC builds where applicable; compare architecture and optimization separately.</li><li>Attempt the investigation without source or the worked solution.</li><li>Write readable C, cite instruction evidence, and test boundary cases.</li><li>Explain the result aloud, then repeat on a different build or input set.</li></ol><p>Many lessons use self-reported completion. Short checkpoints and flags provide practice feedback, not evaluation of the longer learning assignments. Each course has its own downloadable flag lab; comparative case studies add source, real assembly, state tables, and ungraded practice.</p></div>${weeklyPlan()}${outcomeMatrix()}<div class="panel"><h3>Syllabus coverage map</h3><div class="tablewrap"><table class="coverage"><thead><tr><th>Syllabus sequence</th><th>Topic</th><th>Study module</th></tr></thead><tbody>${db.syllabus.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td><a href="#course/${r[2]}">${db.courses.find(c=>c[0]===r[2])[2]} →</a></td></tr>`).join('')}</tbody></table></div></div><div class="panel"><h3>Readiness checklist</h3><p>Before the mock final, independently reconstruct C from an unfamiliar binary; explain x86/x64 calling conventions; recover arrays, switches and structs; debug a stripped ELF and native Windows PE; recognize and resolve the supplied toy anti-analysis obstacles; and validate a persistent behavioral repair with multiple inputs.</p><p>The course’s official exam may cover details beyond this site. Confirm emphasis against instructor materials. For submitted coursework, the supplied syllabus permits AI only with instructor permission, requires disclosure of substantive use, and leaves you responsible for accuracy, originality, and explaining your work. AI is prohibited during exams/quizzes. Independent practice here is separate from an official submission; rehearse the mock final without AI and follow the current instructor policy and D2L instructions.</p><a class="btn" href="#course/workshop">Open investigations & mock final →</a></div>${labResources()}<div class="panel"><h3>Teaching and assessment boundaries</h3><p>Core: assembly, compiled C recognition, Ghidra, dynamic analysis, Windows, anti-analysis, and C reconstruction. Supplement: source auditing, memory-safety/exploitation concepts, sanitizers, and fuzzing from the catalog description. Packing is taught conceptually with an encoded-data model; this is not a practical malware-unpacking course. Browser code blanks check supported text answers; they do not assemble or execute code. This website does not run GDB, Ghidra, native Windows programs, or uploaded executables.</p></div>`}
function searchableLesson(l){return [l.title,l.body,l.code,l.task,...(l.walkthrough||[]),...(l.sections||[]).flatMap(s=>[s.title,s.text,s.code,...(s.table||[]).flat()]),l.practical?.title,l.practical?.brief,l.practical?.start,...(l.practical?.prompts||[]),...(l.practical?.checks||[]).map(row=>row[0]),...(l.references||[]).map(r=>r[0])].filter(Boolean).join(' ').toLowerCase()}
function searchResults(query){const q=query.trim().toLowerCase(),found=db.lessons.filter(l=>!q||searchableLesson(l).includes(q));return `<p class="muted">${found.length} matching lessons</p>${found.map(l=>`<a class="lessonrow" href="#lesson/${l.id}"><span class="circle ${done(l.id)?'done':''}">${done(l.id)?'✓':'→'}</span><div><strong>${esc(l.title)}</strong><small>${esc(db.courses.find(c=>c[0]===l.course)[2])} · ${esc(l.level)}</small></div></a>`).join('')||'<p>No lessons match. Try a broader term such as stack, struct, or Windows.</p>'}`}
function catalog(){return `<div class="eyebrow">SEARCH ALL ${db.lessons.length} LESSONS</div><h1>Find the concept you need.</h1><label class="searchlabel" for="lessonsearch">Search titles, explanations, examples, and practice steps</label><input id="lessonsearch" type="search" placeholder="Try stack frames, switch, MSVC, or signed division…"><div class="panel" id="searchresults">${searchResults('')}</div>`}
function courseLabPanel(id){const l=db.lessons.find(l=>l.id===db.courseLabs?.[id]);if(!l)return '';let solved=(state.flagsSolved||[]).includes(l.id);return `<div class="panel labdownload"><span class="eyebrow">INTERACTIVE LAYER · ${solved?'FLAG FOUND':'BINARY CHALLENGE'}</span><h3>${esc(l.title)}</h3><p>Download a real program, investigate it with Ghidra or a debugger, and enter the flag it prints. Start with the guided build; try the optimized stripped build after you understand the first. Longer learning assignments remain ungraded. Advanced modules also include a separate practical binary with different inputs and task-specific evidence prompts.</p><a class="btn" href="#lesson/${l.id}">${solved?'Revisit the lab':'Open interactive lab'} →</a></div>`}
function binaryDownloads(l){if(!l.downloads)return '';if(l.id===0)return `<p><a class="btn secondary" href="labs/lab.c" download>Download environment smoke-test C source ↓</a></p>`;return `<div class="binarydownloads"><h4>${l.flagDigest?'Download this course’s binary challenge':'Download the comparative learning lab'}</h4>${l.downloads.map(r=>`<p><a class="btn secondary" href="${esc(r[1])}" download>${esc(r[0])} ↓</a></p>`).join('')}<p><a href="labs/interactive-flag-labs.zip" download>All 13 flag labs + Linux/MSVC build scripts ↓</a></p><p class="muted">${l.flagDigest?'Introductory flag ELF executables are Linux x86-64. For native Windows PE, build the supplied C with build-msvc-flags.bat.':'Comparative casebook executables include Linux x64 and x86/32. x64 results were tested; x86 files were format/disassembly checked because this host lacks 32-bit execution support. For native Windows PE, use build-msvc-casebook.bat.'} Use a matching developer prompt for MSVC; those Windows builds require local verification. Sources and worked solutions are optional self-review aids.</p></div>`}
async function checkFlag(l){let feedback=$('#feedback');const value=$('#answer').value.trim();if(!value){feedback.className='feedback error';feedback.textContent='Enter the complete flag first.';return}if(!globalThis.crypto?.subtle){feedback.className='feedback error';feedback.textContent='Flag checks need the localhost server in a current browser. Open the localhost URL from the launcher.';return}try{const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(value)))).map(b=>b.toString(16).padStart(2,'0')).join('');let ok=digest===l.flagDigest;feedback.className='feedback '+(ok?'success':'error');feedback.textContent=ok?'Flag found! Use your notebook to explain the check, decoder, and debugger or Ghidra evidence. This is interactive practice, not a graded assignment.':'That flag does not match this course’s lab. Copy the complete BS{...} output, preserve case, and check that you downloaded the correct course binary.';if(ok){state.flagsSolved=state.flagsSolved||[];if(!state.flagsSolved.includes(l.id))state.flagsSolved.push(l.id);if(!done(l.id))state.done.push(l.id);save()}}catch{feedback.className='feedback error';feedback.textContent='Could not check the flag. Please retry in a current browser using localhost.'}}
function sectionTeaching(l){return `${l.diagram?`<figure class="learningdiagram"><img src="${esc(l.diagram.path)}" alt="${esc(l.diagram.alt)}"><figcaption>${esc(l.diagram.alt)}</figcaption></figure>`:''}${(l.sections||[]).map(section=>`<section class="teachingsection"><h4>${esc(section.title)}</h4>${section.text?`<p>${esc(section.text)}</p>`:''}${section.code?`<details class="listing"><summary>Open the actual instruction listing</summary><pre>${esc(section.code)}</pre></details>`:''}${section.table?`<div class="tablewrap"><table class="coverage"><thead><tr>${section.table[0].map(cell=>`<th scope="col">${esc(cell)}</th>`).join('')}</tr></thead><tbody>${section.table.slice(1).map(row=>`<tr>${row.map(cell=>`<td>${esc(cell)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}</section>`).join('')}`}
function render(){persistDraft();activeLessonId=null;const routeChanged=lastRenderedHash!==location.hash;lastRenderedHash=location.hash;let [route,arg]=(location.hash.slice(1)||'home').split('/');$('#crumb').textContent=({home:'Overview',courses:'Learning path',course:'Course',lesson:'Learning workspace',resources:'Resources',final:'Patch practice',syllabus:'Syllabus coverage',catalog:'Find a lesson',achievements:'Achievements',readiness:'Practical readiness',paths:'Diagnostic & study paths'})[route]||'Overview';document.querySelectorAll('[data-nav]').forEach(a=>{const active=a.dataset.nav===route||(['course','lesson'].includes(route)&&a.dataset.nav==='courses');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#app').innerHTML=route==='paths'?studyPaths():route==='readiness'?readiness():route==='home'?home():route==='courses'?`<div class="eyebrow">A GRADUAL PATH</div><h1>Build understanding, step by step.</h1><p><a href="#paths">Choose the full foundation path or the focused syllabus revision path.</a> Hints and notes stay available; revisit any lesson at any time.</p>${cards()}`:route==='course'?course(arg):route==='lesson'?lesson(arg):route==='resources'?resources():route==='syllabus'?syllabus():route==='catalog'?catalog():route==='final'?final():route==='achievements'?achievements():home();bind(route,arg);const outline=$('.lessonoutline');if(outline&&window.matchMedia?.('(max-width:760px)').matches)outline.open=false;if(routeChanged){window.scrollTo(0,0);focusContent('#app h1')}}
function practicalPanel(l){if(!l.practical)return '';return `<div class="panel"><h3>Practical investigation · ${esc(l.practical.title)}</h3><p>${esc(l.practical.brief)}</p>${l.practical.downloads.map(r=>`<p><a href="${esc(r[1])}" download>${esc(r[0])} ↓</a></p>`).join('')}<pre>${esc(l.practical.start)}</pre><ol>${l.practical.prompts.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${practicalChecks(l)}<p>Keep the original flag exercise as a warm-up. Attempt this guided investigation next, then repeat on the stripped build. Reports are ungraded; compare with the separately downloaded self-review guide after attempting.</p><label for="practicalevidence">Evidence report: addresses, commands, observed state, reconstructed C, tests, and remaining uncertainty</label><textarea id="practicalevidence">${esc(state.evidence?.[l.id]||'')}</textarea><p id="evidencestatus" role="status">Report drafts autosave in this browser.</p><button class="btn secondary" id="saveevidence">Save practical evidence</button></div>`}
function holdoutPanel(l){if(l.id!==94)return '';return `<div class="notice"><h3>Fresh mock-final pack</h3><p>Use one of the three unfamiliar variants below. These programs are separate from the teaching labs. Download only the challenge pack before starting; the review pack contains source and answers. Static inspection can be done on any supported Ghidra host; execution requires the matching OS and architecture.</p><p><a href="labs/readiness/mock-final-challenges.zip" download>Challenge binaries and exam briefs ↓</a></p><p><a href="labs/readiness/mock-final-review.zip" download>After your attempt: source, expected results, MSVC build scripts, and rubric ↓</a></p><h4>Validate your exported data patch</h4><label for="repairtarget">Original binary you patched</label><select id="repairtarget">${['cedar','quartz','willow'].flatMap(v=>['guided-linux-x64','independent-linux-x64','guided-mingw-x64.exe','independent-mingw-x64.exe'].map(t=>`<option value="final-${v}-${t}">${v} · ${t}</option>`)).join('')}</select><p><label for="repairupload">Upload your exported executable (stays in your browser; never executed)</label></p><input type="file" id="repairupload"><p id="repairfeedback" role="status">This checker accepts only the original binary with adjustment changed from 1 to 9. For other instruction repairs, use the local behavioral verifier after your attempt.</p><p>Windows PE downloads are MinGW-w64 GCC builds, not MSVC builds. Rebuild the same original C with the supplied MSVC script for compiler comparison. Live Windows execution is pending verification.</p></div>`}
const outcomes=[['static','Static binary analysis',113,'Identify main, cross-references, imports where applicable, and branch evidence.'],['reconstruct','Recover readable C',119,'Recover loops, fields, types, function contracts and edge-case behavior.'],['debug','Dynamic analysis',116,'Record breakpoint, registers/memory, competing hypotheses, and a repeatable experiment.'],['anti','Recognize and defeat anti-analysis',118,'Explain the toy obstacle, bypass it, and verify normal computation and a persistent repair.']];
function readiness(){return `<h1>Practical readiness</h1><p>Reading completion, correct short answers, solved flags, and practical evidence measure different things. Older completion records are retained; earlier checkpoint results were not recorded separately. These are study diagnostics, not verified grades.</p><div class="stats"><div class="stat"><div><strong>${state.done.length}</strong><small>Marked complete / studied</small></div></div><div class="stat"><div><strong>${(state.checkpoints||[]).length}</strong><small>Short checkpoints correct</small></div></div><div class="stat"><div><strong>${(state.flagsSolved||[]).length}</strong><small>Course flags solved</small></div></div></div>${outcomes.map(([key,title,id,desc])=>`<section class="panel"><h2>${title}</h2><p>${desc}</p><p><a href="#lesson/${id}">Open the diagnostic investigation →</a> · Flag: ${(state.flagsSolved||[]).includes(id)?'solved':'not recorded'} · Behavioral predictions: ${(state.practicalChecks||[]).includes(id)?'matched':'not recorded'} · Practical report: ${String(state.evidence?.[id]||'').trim()?'recorded (ungraded)':'not recorded'}</p><label><input type="checkbox" data-outcome="${key}" ${state.readiness?.[key]?'checked':''}> I attempted the unfamiliar practical task, checked my evidence against the rubric, and can explain it without copying.</label></section>`).join('')}<section class="panel"><h2>Unfamiliar final rehearsal</h2><p>Validated narrow file repairs: ${Object.keys(state.holdout||{}).filter(k=>state.holdout[k]).length}. These checks compare bytes without executing the program.</p><p>Complete lesson 94 using a fresh variant, then review the rubric. Completion and confidence are self-reported; a flag or certificate alone does not demonstrate readiness.</p><a class="btn" href="#lesson/94">Open the mock final →</a></section><section class="panel"><h2>Activity evidence record</h2>${db.lessons.filter(l=>done(l.id)||(state.checkpoints||[]).includes(l.id)||state.evidence?.[l.id]).map(l=>`<p><a href="#lesson/${l.id}">${esc(l.title)}</a><br><small>Study/completion: ${done(l.id)?'recorded':'pending'} · Checkpoint: ${(state.checkpoints||[]).includes(l.id)?'correct':'not recorded'} · Flag: ${(state.flagsSolved||[]).includes(l.id)?'solved':'not recorded'} · Report: ${String(state.evidence?.[l.id]||'').trim()?'recorded, ungraded':'not recorded'}</small></p>`).join('')||'<p>No activity recorded yet.</p>'}</section>`}
function bindReadiness(){document.querySelectorAll('[data-outcome]').forEach(el=>el.onchange=()=>{state.readiness=state.readiness||{};state.readiness[el.dataset.outcome]=el.checked;if(!save())toast('Could not save readiness record')})}

function practicalChecks(l){if(!l.practical.checks?.length)return '';return `<details><summary>Check your behavioral predictions</summary><p>Predict these before running the program. Matching text does not prove tool usage or assess the full investigation.</p>${l.practical.checks.map((row,i)=>`<p><label for="practice${i}">${i+1}. ${esc(row[0])}</label><input id="practice${i}" autocomplete="off"></p>`).join('')}<button class="btn secondary" id="checkpractical" type="button">Check predictions</button><p id="practicefeedback" role="status"></p></details>`}
async function checkHoldoutRepair(e){const feedback=$('#repairfeedback'),file=e.target.files[0],target=$('#repairtarget').value;if(!file)return;if(file.size>1000000){feedback.textContent='File too large (maximum 1 MB).';return}try{const response=await fetch('labs/readiness/repair-manifest.json');if(!response.ok)throw Error('manifest');const manifest=await response.json(),record=manifest[target];const bytes=await file.arrayBuffer();const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(b=>b.toString(16).padStart(2,'0')).join('');if(digest===record.patched){state.holdout=state.holdout||{};state.holdout[target]=true;save();feedback.textContent='Validated: adjustment is 9 and all other original file bytes are preserved. This is a persistent computational data patch. Verify runtime results on multiple quantities with the matching OS; this browser check does not execute the file.'}else feedback.textContent=digest===record.original?'This is the unchanged original. Export your persistent patch first.':'Does not match the specified narrow data patch. Check the selected original build, export format and adjustment location. Alternative behavioral repairs need the local verifier.'}catch{feedback.textContent='Could not validate. Use the localhost server in a current browser, or use the local verifier on your training executable.'}}


let pendingImport=null,importSequence=0;
const progressKey='binary-school-v1',recoveryKey='binary-school-before-import-v1';
function normalizeBackup(raw){
 if(!raw||typeof raw!=='object'||Array.isArray(raw)||!Array.isArray(raw.done)||!raw.notes||typeof raw.notes!=='object'||Array.isArray(raw.notes))throw Error('This is not a Binary School progress backup.');
 const valid=id=>Number.isInteger(id)&&db.lessons.some(l=>l.id===id);
 const ids=value=>Array.isArray(value)?[...new Set(value.filter(valid))]:[];
 const texts=value=>Object.fromEntries(Object.entries(value&&typeof value==='object'&&!Array.isArray(value)?value:{}).filter(([key,text])=>(key==='final'||(String(Number(key))===key&&valid(Number(key))))&&typeof text==='string'));
 const truth=value=>value&&typeof value==='object'&&!Array.isArray(value)?value:{};
 const reviews={};for(const [id,items] of Object.entries(truth(raw.reviews))){if(String(Number(id))!==id||!valid(Number(id)))continue;reviews[id]=Object.fromEntries(Object.entries(truth(items)).filter(([key,val])=>/^\d{1,2}$/.test(key)&&typeof val==='boolean'));}
 return {learningPath:['foundation','revision'].includes(raw.learningPath)?raw.learningPath:'',diagnostic:Array.isArray(raw.diagnostic)?raw.diagnostic.filter(id=>(db.studyPlan?.diagnostic||[]).some(q=>q.id===id)):[],done:ids(raw.done),notes:texts(raw.notes),exam:raw.exam===true,name:typeof raw.name==='string'?raw.name.slice(0,80):'',checkpoints:ids(raw.checkpoints),practicalChecks:ids(raw.practicalChecks),flagsSolved:ids(raw.flagsSolved).filter(id=>db.lessons.find(l=>l.id===id).flagDigest),evidence:texts(raw.evidence),reviews,readiness:Object.fromEntries(outcomes.map(([key])=>[key,truth(raw.readiness)[key]===true])),holdout:Object.fromEntries(Object.entries(truth(raw.holdout)).filter(([key,val])=>/^final-(cedar|quartz|willow)-(guided|independent)-(linux-x64|mingw-x64\.exe)$/.test(key)&&val===true))};
}
function mergeBackups(current,incoming){
 const a=normalizeBackup(current),b=normalizeBackup(incoming),result={...a};
 for(const key of ['done','checkpoints','practicalChecks','flagsSolved'])result[key]=[...new Set([...a[key],...b[key]])];
 for(const key of ['notes','evidence']){result[key]={...a[key]};for(const [id,text] of Object.entries(b[key])){const existing=result[key][id];result[key][id]=!existing?text:!text||existing===text||existing.endsWith('\n\n--- Imported backup ---\n'+text)||existing.split('\n\n--- Imported backup ---\n').includes(text)?existing:existing+'\n\n--- Imported backup ---\n'+text;}}
 for(const key of ['readiness','holdout']){result[key]={...a[key]};for(const [id,val] of Object.entries(b[key]))result[key][id]=!!(result[key][id]||val);}
 result.reviews={...a.reviews};for(const [id,items] of Object.entries(b.reviews)){result.reviews[id]={...a.reviews[id]};for(const [key,val] of Object.entries(items))result.reviews[id][key]=!!(result.reviews[id][key]||val);}
 result.learningPath=a.learningPath||b.learningPath;result.diagnostic=[...new Set([...a.diagnostic,...b.diagnostic])];result.exam=a.exam||b.exam;result.name=a.name||b.name;return result;
}
function importCounts(s){return `${s.done.length} study/completion entries, ${Object.values(s.notes||{}).filter(x=>typeof x==='string'&&x.trim()).length} notes, ${Object.values(s.evidence||{}).filter(x=>typeof x==='string'&&x.trim()).length} practical reports, ${(s.flagsSolved||[]).length} flags, ${(s.checkpoints||[]).length} checkpoints`;}
function showImportPreview(message=''){
 const panel=$('#importpreview');if(!panel)return;
 if(!pendingImport){panel.innerHTML=message?`<p role="status">${esc(message)}</p>`:'';return;}
 const merged=mergeBackups(state,pendingImport.data);
 panel.innerHTML=`<h4 id="importheading">Preview: ${esc(pendingImport.name)}</h4><p>Current browser: ${esc(importCounts(state))}.<br>Selected backup: ${esc(importCounts(pendingImport.data))}.</p><p>Merge result: ${esc(importCounts(merged))}. Existing text stays first; different text for the same lesson is appended under “Imported backup.” Completion and successful checks are combined. Your current certificate name is retained when present.</p><p>Replace discards the current record and uses only the selected backup, including its name and patch/readiness results. Missing newer fields in old backups become empty. Unknown lesson IDs and unsupported fields are ignored.</p><label class="reviewitem"><input type="checkbox" id="confirmreplace"> I understand Replace will remove current records that are absent from this backup.</label><p><button class="btn" id="mergeimport">Merge with current progress</button> <button class="btn secondary" id="replaceimport">Replace current progress</button> <button class="btn secondary" id="cancelimport">Cancel</button></p><p id="importfeedback" role="status">Your progress has not changed. A pre-import snapshot and backup download are requested before either option is applied.</p>`;
 focusContent('#importheading',false);$('#mergeimport').onclick=()=>applyImport('merge');$('#replaceimport').onclick=()=>applyImport('replace');$('#cancelimport').onclick=()=>{importSequence++;pendingImport=null;$('#import').value='';showImportPreview('Import canceled. Your progress is unchanged.');focusContent('#chooseimport');};
}
async function previewImport(file){
 const sequence=++importSequence;pendingImport=null;showImportPreview('Reading backup; your progress is unchanged.');if(!file){showImportPreview();return;}
 try{if(file.size>5000000)throw Error('Backup is too large (maximum 5 MB).');const data=normalizeBackup(JSON.parse(await file.text()));if(sequence!==importSequence)return;pendingImport={name:file.name||'Progress backup',data};showImportPreview();}catch(error){if(sequence!==importSequence)return;pendingImport=null;showImportPreview(error instanceof SyntaxError?'Invalid JSON backup. Your progress is unchanged.':error.message||'Invalid backup. Your progress is unchanged.');}
}
function applyImport(mode){
 if(!pendingImport)return;const feedback=$('#importfeedback');
 if(mode==='replace'&&!$('#confirmreplace').checked){feedback.textContent='Confirm the replacement consequence above, or choose Merge to retain your current records.';return;}
 const before=JSON.stringify(state,null,2),candidate=mode==='merge'?mergeBackups(state,pendingImport.data):pendingImport.data;
 try{localStorage.setItem(recoveryKey,before);download('binary-school-progress-before-import.json',before,'application/json');localStorage.setItem(progressKey,JSON.stringify(candidate));}catch{feedback.textContent='Import was not applied. Could not store the recovery snapshot or new progress, or request the backup download. Export your current progress manually and check browser storage/download settings before retrying.';return;}
 state=candidate;pendingImport=null;render();focusContent('#app h1',false);toast(mode==='merge'?'Progress merged; pre-import recovery is available.':'Progress replaced; pre-import recovery is available.');
}
function bindResources(){
 $('#export').onclick=()=>download('binary-school-progress.json',JSON.stringify(state,null,2),'application/json');
 $('#chooseimport').onclick=()=>$('#import').click();$('#import').onchange=e=>previewImport(e.target.files[0]);
 $('#recoverimport').onclick=()=>{importSequence++;pendingImport=null;try{const text=localStorage.getItem(recoveryKey);if(!text){showImportPreview('No pre-import recovery snapshot is stored in this browser.');return;}pendingImport={name:'Pre-import recovery snapshot',data:normalizeBackup(JSON.parse(text))};showImportPreview();}catch{showImportPreview('Could not read the pre-import recovery snapshot. Your current progress is unchanged.');}};
 showImportPreview();
}


function activeStudyLessons(){if(state.learningPath==='revision'&&db.studyPlan){const ids=[...new Set(db.studyPlan.weeks.flatMap(w=>w.lessons))];const list=ids.map(id=>db.lessons.find(l=>l.id===id)).filter(Boolean);const hashId=Number((location.hash||'').split('/')[1]);if(location.hash?.startsWith('#lesson/')&&!ids.includes(hashId))return db.lessons;return list}return state.learningPath==='foundation'?coreLessons():db.lessons}
function weeklyPlan(){if(!db.studyPlan)return '';return `<section class="panel"><h2>Syllabus revision route</h2><p>Use this route if you already know C, x86 and Linux. Start with the diagnostic; complete the full linked module whenever an investigation exposes a gap. Time ranges are planning estimates, not deadlines or guarantees; tool setup may take longer.</p>${db.studyPlan.weeks.map(w=>`<section class="teachingsection"><h3>${esc(w.week)} · ${esc(w.topic)}</h3><p><strong>Prerequisite:</strong> ${esc(w.prerequisite)}.<br><strong>Plan:</strong> ${esc(w.effort)}.</p><ul>${w.lessons.map(id=>{const l=db.lessons.find(l=>l.id===id);return `<li><a href="#lesson/${id}">${done(id)?'✓ ':''}${esc(l.title)}</a></li>`}).join('')}</ul><p><strong>Evidence target:</strong> ${esc(w.deliverable)} <a href="#lesson/${w.target}">Record it in the investigation notebook →</a></p><p><a href="#course/${w.module}">Need a slower ramp? Study the complete ${esc(db.courses.find(c=>c[0]===w.module)[2])} module →</a></p></section>`).join('')}</section>`}
function outcomeMatrix(){return `<section class="panel"><h2>Four outcomes, concrete evidence</h2><div class="tablewrap"><table class="coverage"><thead><tr><th scope="col">Outcome</th><th scope="col">Investigation</th><th scope="col">Evidence and self-review</th></tr></thead><tbody><tr><td>Static analysis</td><td><a href="#lesson/113">Cross-reference practical</a> · <a href="#lesson/117">PE investigation</a></td><td>Recover function boundaries, arguments, data references, imports and justified names; cite instructions and addresses.</td></tr><tr><td>Reconstruct C</td><td><a href="#lesson/119">Complete pricing program</a> · <a href="#lesson/94">Unfamiliar final</a></td><td>Readable types, layout, loops, parsing and returns; compare ordinary, boundary and invalid inputs against the binary.</td></tr><tr><td>Dynamic analysis</td><td><a href="#lesson/116">Stripped debugger practical</a> · <a href="#lesson/91">Native Windows</a></td><td>Reproducible breakpoint and register/memory state that distinguish two hypotheses; record OS, architecture and tools.</td></tr><tr><td>Defeat anti-analysis</td><td><a href="#lesson/78">Real Windows debugger-dependent path</a> · <a href="#lesson/118">Encoded toy</a> · <a href="#lesson/94">Persistent repair</a></td><td>Explain the obstacle, verify a bypass and distinguish temporary live-state changes from an exported patch. Test multiple inputs.</td></tr></tbody></table></div><p><a href="#readiness">Review recorded evidence and self-assessed readiness →</a> Reports and rubric scores remain ungraded.</p></section>`}
function studyPaths(){const questions=db.studyPlan?.diagnostic||[],revision=[...new Set((db.studyPlan?.weeks||[]).flatMap(w=>w.lessons))];return `<h1>Choose a path that fits your starting point.</h1><p>The syllabus assumes C, x86 assembly and Linux familiarity. This diagnostic checks a few prerequisite ideas; it does not establish debugger competence, give course credit, or mark lessons complete. You can choose either path and change it later without losing progress.</p><section class="panel"><h2>Prerequisite diagnostic · about 10 minutes</h2><form id="diagnosticform">${questions.map((q,i)=>`<p><label for="diagnostic${i}">${esc(q.prompt)}</label><input id="diagnostic${i}" autocomplete="off" required></p>`).join('')}<button class="btn">Check prerequisites</button></form><div id="diagnosticfeedback" role="status"></div><p>Previous diagnostic: ${Array.isArray(state.diagnostic)?state.diagnostic.length:0} / ${questions.length} answers matched. Results suggest what to revisit; they are not a grade.</p></section><section class="panel"><h2>Foundation path · ${coreLessons().length} activities</h2><p>For learners building C/assembly/tool skills. Start with environment setup, then follow all core modules with guided examples before independent investigations. Allow roughly 60–120 hours, adjusted to your starting skills and tool setup.</p><button class="btn secondary" data-path="foundation" aria-pressed="${state.learningPath==='foundation'}">Choose foundation path</button></section><section class="panel"><h2>CSC-428 revision path · ${revision.length} selected activities</h2><p>For learners who already have the syllabus prerequisites. Follow the weekly targets below, use full modules to repair gaps, and finish with unfamiliar binaries. Plan roughly 25–50 hours; Windows setup and missed prerequisites can extend this.</p><button class="btn secondary" data-path="revision" aria-pressed="${state.learningPath==='revision'}">Choose revision path</button></section><p id="pathstatus" role="status">Selected path: ${state.learningPath==='revision'?'syllabus revision':state.learningPath==='foundation'?'foundation':'none yet'}. <a href="#lesson/${next().id}">Open next activity →</a></p>${weeklyPlan()}${outcomeMatrix()}`}
function bindStudyPaths(){document.querySelectorAll('[data-path]').forEach(button=>button.onclick=()=>{state.learningPath=button.dataset.path;if(!save()){$('#pathstatus').textContent='Path selected for this visit, but browser storage is unavailable. Export your progress to keep it.';return;}render();focusContent('#pathstatus',false);toast('Study path saved. Existing progress is preserved.')});$('#diagnosticform').onsubmit=e=>{e.preventDefault();const questions=db.studyPlan.diagnostic;const results=questions.map((q,i)=>matchBlank($('#diagnostic'+i).value.trim(),q.answer));questions.forEach((q,i)=>$('#diagnostic'+i).setAttribute('aria-invalid',String(!results[i])));state.diagnostic=questions.filter((q,i)=>results[i]).map(q=>q.id);const stored=save();$('#diagnosticfeedback').innerHTML=`<p>${results.filter(Boolean).length} / ${questions.length} matched. ${results.every(Boolean)?'Consider the revision route if you can also complete the local environment smoke test.':'Use the foundation route or revisit the linked prerequisites before the corresponding investigation.'} ${stored?'':'Results could not be saved.'}</p><ul>${questions.map((q,i)=>`<li>${results[i]?'✓':'Revisit'} ${esc(q.explain)} <a href="#lesson/${q.lesson}">Practice this prerequisite →</a></li>`).join('')}</ul><p><a href="#lesson/0">Now demonstrate a working compile/run/debug environment.</a> Text answers alone cannot establish that the tools work.</p>`;};}


function focusContent(selector,preventScroll=true){const element=$(selector);if(element&&typeof element.focus==='function'){if(!element.matches?.('a[href],button,input,textarea,select,summary,[tabindex]'))element.setAttribute('tabindex','-1');element.focus({preventScroll})}}
const skipContent=$('#skipcontent');if(skipContent)skipContent.onclick=e=>{e.preventDefault();focusContent('#main-content',false)};

window.addEventListener('beforeunload',e=>{if(persistDraft()===false){e.preventDefault();e.returnValue=''}});
window.addEventListener('pagehide',persistDraft);

fetch('curriculum.json').then(r=>r.json()).then(x=>{db=x;render();window.addEventListener('hashchange',render)}).catch(()=>$('#app').textContent='Could not load the curriculum. Please refresh.');
